export type PlantationCategory =
  | "FRUIT_TREES"
  | "TIMBER"
  | "MEDICINAL"
  | "ORNAMENTAL"
  | "VEGETABLE"
  | "GRAIN"
  | "FLOWER"
  | "OTHER";

export interface PlantationRecord {
  id?: string;
  name: string;
  category: PlantationCategory;
  description?: string;
  latitude: number;
  longitude: number;
  area?: number;
  createdAt?: string;
  updatedAt?: string;
}

export const PLANTATION_CATEGORIES: {
  value: PlantationCategory;
  label: string;
  color: string;
  markerColor: string;
}[] = [
  { value: "FRUIT_TREES",  label: "Fruit Trees",   color: "#16a34a", markerColor: "green" },
  { value: "TIMBER",        label: "Timber",        color: "#92400e", markerColor: "brown" },
  { value: "MEDICINAL",    label: "Medicinal",     color: "#7c3aed", markerColor: "purple" },
  { value: "ORNAMENTAL",   label: "Ornamental",    color: "#ec4899", markerColor: "pink" },
  { value: "VEGETABLE",     label: "Vegetable",     color: "#eab308", markerColor: "yellow" },
  { value: "GRAIN",         label: "Grain",         color: "#f97316", markerColor: "orange" },
  { value: "FLOWER",        label: "Flower",        color: "#e11d48", markerColor: "red" },
  { value: "OTHER",         label: "Other",         color: "#6b7280", markerColor: "gray" },
];

export function getCategoryColor(category: PlantationCategory): string {
  return PLANTATION_CATEGORIES.find((c) => c.value === category)?.color ?? "#6b7280";
}

export function getCategoryLabel(category: PlantationCategory): string {
  return PLANTATION_CATEGORIES.find((c) => c.value === category)?.label ?? "Other";
}

export const QUEUE_OP = {
  CREATE: "CREATE",
  UPDATE: "UPDATE",
  DELETE: "DELETE",
} as const;

export type QueueOp = (typeof QUEUE_OP)[keyof typeof QUEUE_OP];

export interface OfflineQueueItem {
  id?: number;
  op: QueueOp;
  data: PlantationRecord;
  timestamp: string;
  synced: boolean;
}
