"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import type { PlantationRecord, OfflineQueueItem, QueueOp } from "@/types/plantation";
import {
  getAllPlantations,
  putPlantation,
  deletePlantation as dbDelete,
  enqueue,
  getUnsyncedItems,
  markSynced,
  clearSyncedItems,
  getQueueSize,
} from "@/lib/offline-db";

interface UseOfflineQueueOptions {
  autoSync?: boolean;
  syncIntervalMs?: number;
}

interface UseOfflineQueueReturn {
  items: PlantationRecord[];
  queueDepth: number;
  isSyncing: boolean;
  add: (data: PlantationRecord) => Promise<string>;
  update: (data: PlantationRecord) => Promise<void>;
  remove: (id: string) => Promise<void>;
  refresh: () => Promise<void>;
  sync: () => Promise<void>;
  error: string | null;
}

export function useOfflineQueue(
  opts: UseOfflineQueueOptions = {}
): UseOfflineQueueReturn {
  const { autoSync = true, syncIntervalMs = 15_000 } = opts;

  const [items, setItems] = useState<PlantationRecord[]>([]);
  const [queueDepth, setQueueDepth] = useState(0);
  const [isSyncing, setIsSyncing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const syncLock = useRef(false);

  const refresh = useCallback(async () => {
    try {
      const records = await getAllPlantations();
      setItems(records);
      const qd = await getQueueSize();
      setQueueDepth(qd);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Failed to load plantations");
    }
  }, []);

  // Queue an operation for later sync
  const queueOp = useCallback(async (op: QueueOp, data: PlantationRecord) => {
    try {
      await enqueue({
        op,
        data,
        timestamp: new Date().toISOString(),
        synced: false,
      });
      const qd = await getQueueSize();
      setQueueDepth(qd);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Failed to enqueue operation");
    }
  }, []);

  // Write-through: persist to IndexedDB immediately + queue for server sync
  const add = useCallback(
    async (data: PlantationRecord): Promise<string> => {
      const id = await putPlantation(data);
      const record = { ...data, id };
      await queueOp("CREATE", record);
      await refresh();
      return id;
    },
    [queueOp, refresh]
  );

  const update = useCallback(
    async (data: PlantationRecord): Promise<void> => {
      if (!data.id) return;
      await putPlantation(data);
      await queueOp("UPDATE", data);
      await refresh();
    },
    [queueOp, refresh]
  );

  const remove = useCallback(
    async (id: string): Promise<void> => {
      const existing = await getAllPlantations();
      const record = existing.find((r) => r.id === id);
      await dbDelete(id);
      if (record) {
        await queueOp("DELETE", record);
      }
      await refresh();
    },
    [queueOp, refresh]
  );

  // Sync unsynced items to server
  const sync = useCallback(async () => {
    if (syncLock.current) return;
    syncLock.current = true;
    setIsSyncing(true);
    setError(null);

    try {
      const pending = await getUnsyncedItems();
      if (pending.length === 0) {
        await clearSyncedItems();
        setIsSyncing(false);
        syncLock.current = false;
        return;
      }

      for (const item of pending) {
        try {
          const res = await fetch("/api/plantation/sync", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(item),
          });
          if (!res.ok) throw new Error(`Sync failed: ${res.status}`);
          await markSynced(item.id!);
        } catch (e) {
          setError(
            e instanceof Error ? e.message : "Sync error on one item"
          );
        }
      }

      await clearSyncedItems();
      const qd = await getQueueSize();
      setQueueDepth(qd);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Sync failed");
    } finally {
      setIsSyncing(false);
      syncLock.current = false;
    }
  }, []);

  // Auto-sync on interval
  useEffect(() => {
    if (!autoSync) return;
    const interval = setInterval(() => {
      sync();
    }, syncIntervalMs);
    return () => clearInterval(interval);
  }, [autoSync, syncIntervalMs, sync]);

  // Initial load
  useEffect(() => {
    refresh();
  }, [refresh]);

  return { items, queueDepth, isSyncing, add, update, remove, refresh, sync, error };
}
